// Find existing profile by comparing values
function findExistingProfileKey(
  tagsByProfile: Map<ProfileKey, string[]>,
  profile: ProfileKey
): ProfileKey {
  for (const [key] of tagsByProfile) {
    if (
      typeof key === "string" &&
      typeof profile === "string" &&
      key === profile
    ) {
      return key;
    }
    if (
      typeof key === "object" &&
      typeof profile === "object" &&
      JSON.stringify(key) === JSON.stringify(profile)
    ) {
      return key;
    }
    if (key === profile) {
      return key;
    }
  }
  return undefined;
}

